private final class ProjectiveLayerGate:@unchecked Sendable{let condition=NSCondition();var ready=false;func wait(){condition.lock();while !ready{condition.wait()};condition.unlock()};func release(){condition.lock();ready=true;condition.broadcast();condition.unlock()}}
final class ProjectiveLayerTransformWorkflowTests:XCTestCase {
  func fixture(_ depth:PixelDepth = .u8)throws->CraftDocument{try LayerCollectionTransformWorkflowTests().fixture(depth)}
  @MainActor func select(_ s:EditorStore){s.selectedLayerIDs=Set(s.document.layers.map(\.id))}
  @MainActor func distorted(_ draft:TransformDraft)->TransformDraft{draft.selectionDragging(handle:0,from:draft.handles[0],to:.init(x:draft.handles[0].x+3,y:draft.handles[0].y+2),mode:.distort,shift:false,option:false)}
  @MainActor func testNativeProjectivePreviewSixModesReferenceAndCancelStayNonDestructive()async throws {
    let source=try fixture(),s=EditorStore(document:source);defer{s.cancelTransform();s.renderTask?.cancel()};select(s);s.beginTransform();let session=try XCTUnwrap(s.selectionTransform),draft=try XCTUnwrap(s.transformDraft);XCTAssertTrue(draft.collectionProjective);XCTAssertEqual(s.selectionTransformModes,SelectionTransformMode.allCases);s.chooseSelectionTransformMode(.distort);let next=distorted(draft);XCTAssertNil(try next.selectionProjection.affineValue());s.updateTransform(next);await SelectedPixelTransformWorkflowTests().settle(session);XCTAssertNotNil(session.pixelPreview);XCTAssertNil(session.error);XCTAssertEqual(s.document,source);XCTAssertTrue(s.session.undoStack.isEmpty);s.cancelTransform();XCTAssertTrue(session.closed);XCTAssertEqual(s.document,source)
  }
  @MainActor func testPerspectiveCommitUndoRedoActions38AndNativePersistence()async throws {
    let source=try fixture(),doc=CraftNSDocument(model:source),s=doc.store;defer{s.cancelTransform();s.renderTask?.cancel();doc.updateChangeCount(.changeCleared);doc.close()};select(s);try s.session.startActionRecording(name:"Perspective");s.beginTransform();let draft=try XCTUnwrap(s.transformDraft),session=try XCTUnwrap(s.selectionTransform),next=draft.selectionDragging(handle:0,from:draft.handles[0],to:.init(x:draft.handles[0].x+3,y:draft.handles[0].y),mode:.perspective,shift:false,option:false);s.updateTransform(next);s.commitTransform();await session.commitTask?.value;XCTAssertNil(session.error);XCTAssertEqual(s.session.undoStack.count,1);XCTAssertTrue(doc.isDocumentEdited);var expected=source;try Command.transformLayers(.init(layerIDs:source.layers.map(\.id),projection:next.selectionProjection)).apply(to:&expected);XCTAssertEqual(s.document,expected);XCTAssertEqual(try NativeArchive.decode(NativeArchive.encodeChunked(s.document)),expected);var file=ActionLibraryFile();file.actions=[try XCTUnwrap(s.session.actionRecording?.snapshot)];let bytes=try file.encoded();XCTAssertEqual(try ActionLibraryFile.decode(bytes).version,38);var bad=try XCTUnwrap(JSONSerialization.jsonObject(with:bytes) as? [String:Any]);bad["version"]=37;XCTAssertThrowsError(try ActionLibraryFile.decode(JSONSerialization.data(withJSONObject:bad)));var replay=source;try file.actions[0].apply(to:&replay);XCTAssertEqual(replay,expected);_=await s.requestHistory(redo:false).value;XCTAssertEqual(s.document,source);_=await s.requestHistory(redo:true).value;XCTAssertEqual(s.document,expected)
  }
  @MainActor func testActualCanvasCommandDragCapturedModeAndAll16EffectiveCursors()async throws {
    _=NSApplication.shared;let source=try fixture(),s=EditorStore(document:source);select(s);s.beginTransform();s.zoom=8;let canvas=CraftCanvas(store:s),window=NSWindow(contentRect:.init(x:0,y:0,width:400,height:300),styleMask:.borderless,backing:.buffered,defer:false);window.isReleasedWhenClosed=false;window.contentView=canvas;canvas.frame=window.contentView!.bounds;canvas.synchronizeViewport();defer{s.cancelTransform();s.renderTask?.cancel();window.contentView=nil;window.close()};let draft=try XCTUnwrap(s.transformDraft),flags:[NSEvent.ModifierFlags]=[.control,.command,.option,.shift];canvas.cursorLocationInView=canvas.viewPoint(draft.handles[0]);for bits in 0..<16{let f=flags.enumerated().reduce(NSEvent.ModifierFlags()){r,p in bits&(1<<p.offset) != 0 ? r.union(p.element):r};canvas.updateCursorModifiers(f);let mode=draft.selectionMode(handle:0,modifiers:f);XCTAssertEqual(canvas.toolCursor,ToolCursor.selectionTransform(mode,handle:0,flags:f,proportional:draft.proportional))};let h=SelectedPixelMoveWorkflowTests(),start=draft.handles[0],end=CGPoint(x:start.x+3,y:start.y+2);canvas.mouseDown(with:h.mouse(.leftMouseDown,start,canvas:canvas,window:window,flags:.command));canvas.mouseDragged(with:h.mouse(.leftMouseDragged,end,canvas:canvas,window:window,flags:[]));XCTAssertNil(try XCTUnwrap(s.transformDraft).selectionProjection.affineValue());XCTAssertEqual(s.document,source);canvas.mouseUp(with:h.mouse(.leftMouseUp,end,canvas:canvas,window:window));let session=try XCTUnwrap(s.selectionTransform);s.commitTransform();await session.commitTask?.value;XCTAssertNil(session.error);XCTAssertNotEqual(s.document,source)
  }
  @MainActor func testHTTPProjectiveDepthMethodsProfilesSmartMasksMatchNativeAndUndo()async throws {
    let h=AutomationTests();try await h.withService(pressedMouseButtons:{0}){service,doc in let s=doc.store;for depth in PixelDepth.allCases{for method in Resampling.allCases{var source=try self.fixture(depth);source.workingICC=try ColorManagement.importedProfile(XCTUnwrap(CGColorSpace(name:CGColorSpace.displayP3)?.copyICCData() as Data?),depth:depth);if method == .nearest{try SmartObjectIO.convert(in:source,selected:[source.layers[0].id]).apply(to:&source);source.layers[0].mask=try Surface(width:32,height:24,depth:depth,fill:.white);source.layers[0].maskProperties=MaskProperties()};s.session=EditorSession(document:source);self.select(s);try service.share(doc);let matrix=try ProjectiveTransform([1,0.1,2,0.05,1,1,0.01,0.005,1]),params:[String:Any]=["layerIDs":source.layers.map{$0.id.uuidString},"matrix":matrix.values,"interpolation":method.rawValue],code=try await h.edit(service,doc,"layers.transform",params);XCTAssertEqual(code,200);XCTAssertEqual(s.actionState["supportedVersions"] as? [Int],Array(1...ActionLibraryFile.maximumVersion));XCTAssertTrue((AutomationCommand.actionSchema("data")["description"] as? String)?.contains("1–\(ActionLibraryFile.maximumVersion)") == true);var expected=source;try Command.transformLayers(.init(layerIDs:source.layers.map(\.id),projection:matrix,interpolation:method)).apply(to:&expected);XCTAssertEqual(s.document,expected);XCTAssertEqual(try NativeArchive.encodeChunked(s.document),try NativeArchive.encodeChunked(expected));XCTAssertNoThrow(try Renderer.render(s.document));_=await s.requestHistory(redo:false).value;XCTAssertEqual(s.document,source)}}}
  }
  @MainActor func testInvalidBusyStaleRevokedAndCancelledProjectiveWorkPublishesNothing()async throws {
    let h=AutomationTests();try await h.withService(pressedMouseButtons:{0}){service,doc in let source=try self.fixture(),s=doc.store;s.session=EditorSession(document:source);self.select(s);try service.share(doc);let params:[String:Any]=["layerIDs":source.layers.map{$0.id.uuidString},"matrix":[1,0.1,2,0.05,1,1,0.01,0.005,1]],stale=try await h.edit(service,doc,"layers.transform",params,revision:"old");XCTAssertEqual(stale,409);s.beginTransform();let busy=try await h.edit(service,doc,"layers.transform",params);XCTAssertEqual(busy,409);s.cancelTransform();let gate=ProjectiveLayerGate();defer{gate.release()};s.layerCollectionTransformPreparation={_,r in gate.wait();try Task.checkCancellation();return .transformLayers(r)};let task=Task{try await h.edit(service,doc,"layers.transform",params)};let until=Date().addingTimeInterval(10);while !s.geometryBusy && Date()<until{await Task.yield()};service.revoke(try XCTUnwrap(service.shares.first?.id));gate.release();let code=try await task.value;XCTAssertEqual(code,409);XCTAssertEqual(s.document,source);let native=ProjectiveLayerGate();defer{native.release()};s.layerCollectionTransformPreparation={_,r in native.wait();try Task.checkCancellation();return .transformLayers(r)};s.beginTransform();s.updateTransform(self.distorted(try XCTUnwrap(s.transformDraft)));let session=try XCTUnwrap(s.selectionTransform);s.commitTransform();s.cancelTransform();native.release();await session.commitTask?.value;XCTAssertEqual(s.document,source)}
  }
  @MainActor func testSingleRasterUsesSharedControlsAndMixedShapeKeepsHonestAvailability()throws {
    let s=EditorStore(document:try fixture());defer{s.cancelTransform();s.renderTask?.cancel()};s.selectedLayerIDs=[try XCTUnwrap(s.document.activeLayerID)];s.beginTransform();XCTAssertEqual(s.transformDraft?.collectionLayerIDs,[try XCTUnwrap(s.document.activeLayerID)]);XCTAssertEqual(s.transformDraft?.collectionProjective,true);s.cancelTransform();var mixed=s.document;mixed.layers.append(Layer(name:"Shape",content:.shape(.init(kind:.rectangle,width:4,height:3,color:.white))));s.session=EditorSession(document:mixed);select(s);s.beginTransform();XCTAssertEqual(s.transformDraft?.collectionProjective,false);XCTAssertEqual(s.selectionTransformModes,[.free,.scale,.rotate,.skew]);s.chooseSelectionTransformMode(.distort);XCTAssertEqual(s.transformDraft?.selectionMode,.free);let state=try JSONDecoder().decode(AutomationValue.self,from:JSONSerialization.data(withJSONObject:s.layerCollectionTransformState));XCTAssertNoThrow(try BrushAPI.merge(state,schema:LayerCollectionTransformAPI.stateSchema))
  }
  @MainActor func testCoalescedProjectivePreviewIsBoundedAndReadClosesSession()async throws {
    var source=try fixture();try Command.imageSize(4096,3072,source.pixelsPerInch,.nearest).apply(to:&source);let doc=CraftNSDocument(model:source),s=doc.store;defer{s.cancelTransform();s.renderTask?.cancel();doc.updateChangeCount(.changeCleared);doc.close()};select(s);s.beginTransform();let session=try XCTUnwrap(s.selectionTransform),draft=try XCTUnwrap(s.transformDraft);for i in 1...20{var next=draft;next.selectionQuad![0].x+=Double(i)*5;s.updateTransform(next)};await SelectedPixelTransformWorkflowTests().settle(session);XCTAssertNotNil(session.pixelPreview);XCTAssertEqual(session.pixelPreview?.image.width,1024);XCTAssertNil(session.error);XCTAssertEqual(s.document,source);XCTAssertTrue(s.session.undoStack.isEmpty);try doc.read(from:NativeArchive.encodeChunked(source),ofType:CraftNSDocument.nativeType);XCTAssertTrue(session.closed)
