  func testProjectiveOwnedOutputsCapturedForIndependentRGBAReader()throws {
    let matrices:[[Double]]=[[1,0.1,2,0.05,1,1,0.01,0.005,1],[1,0,3,0,1,2,0.02,0,1],[1,0.2,-1,0,1,2,0,0.01,1],[1,0,1,0.1,1,-2,-0.005,0.002,1]];var rows:[[String:Any]]=[]
    for smart in [false,true]{for matrix in matrices{var d=try CraftDocument(width:20,height:16),a=Layer(name:"A",content:.raster(try Surface(width:3,height:2,fill:Pixel(1,0,0)))),b=Layer(name:"B",content:.raster(try Surface(width:4,height:3,fill:Pixel(0,0,1))));a.x=2;a.y=3;b.x=9;b.y=6;if smart{a.smartObject=try SmartObject(fileName:"owned.png",mediaType:"image/png",data:Data([1,2,3]),width:3,height:2);var mask=try Surface(width:3,height:2,fill:.black);for y in 0..<2{for x in 0..<2{mask.setPixel(x:x,y:y,.white)}};a.mask=mask;a.maskProperties=MaskProperties()};d.layers=[a,b];d.activeLayerID=b.id;try Command.transformLayers(.init(layerIDs:d.layers.map(\.id),projection:ProjectiveTransform(matrix),interpolation:.nearest)).apply(to:&d);let out=try Renderer.render(d).surface;var rgba:[Int]=[];for y in 0..<16{for x in 0..<20{let p=out.pixel(x:x,y:y);rgba += [p.r,p.g,p.b,p.a].map{Int((unit($0)*255).rounded())}}};rows.append(["matrix":matrix,"smartMasked":smart,"rgba":rgba])}}
    if let path=ProcessInfo.processInfo.environment["PHOTATO_TEST_CAPTURE_DIR"]{let dir=URL(fileURLWithPath:path);try FileManager.default.createDirectory(at:dir,withIntermediateDirectories:true);try JSONSerialization.data(withJSONObject:["width":20,"height":16,"rows":rows],options:.sortedKeys).write(to:dir.appendingPathComponent("projective-layer-transform-analytical.json"))}
  }
